<?php
use App\Support\{IncentiveMath,Money};
it('earns only collected value excluding the original VAT snapshot',function(){expect(IncentiveMath::earned(11800,1800,5900,100,1000))->toBe(['paid_net_value'=>5000,'points_total'=>50,'commission_total'=>500]);expect(IncentiveMath::earned(11800,1800,0,100,1000)['points_total'])->toBe(0);});
it('uses cumulative floor points and exact commission rounding without fragmented payment bonuses',function(){expect(IncentiveMath::earned(1000,0,99,100,1000)['points_total'])->toBe(0);expect(IncentiveMath::earned(1000,0,100,100,1000)['points_total'])->toBe(1);expect(IncentiveMath::earned(1000,0,999,100,1000)['commission_total'])->toBe(100);expect(IncentiveMath::earned(1000,0,0,null,null)['commission_total'])->toBe(0);});
it('ceilings demand using exact atoms and transparent calendar-day windows',function(){expect(IncentiveMath::ceilingDemand(10,3,7))->toBe(24);expect(IncentiveMath::ceilingDemand(1001,30,7))->toBe(234);expect(IncentiveMath::ceilingDemand(0,30,7))->toBe(0);});
it('rejects invalid money rates and unsafe demand overflow',function(){expect(fn()=>IncentiveMath::earned(10,11,10,1,100))->toThrow(InvalidArgumentException::class);expect(fn()=>IncentiveMath::earned(10,0,11,1,100))->toThrow(InvalidArgumentException::class);expect(fn()=>IncentiveMath::ceilingDemand(PHP_INT_MAX,1,90))->toThrow(OverflowException::class);expect(IncentiveMath::earned(Money::MAX_AMOUNT,0,Money::MAX_AMOUNT,1,10000)['commission_total'])->toBe(Money::MAX_AMOUNT);});
